#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
};

void append(Node** headRef, int value) {
    Node* newNode = new Node();
    newNode->data = value;
    newNode->next = nullptr;
    if (*headRef == nullptr) {
        *headRef = newNode;
        return;
    }
    Node* last = *headRef;
    while (last->next != nullptr) {
        last = last->next;
    }
    last->next = newNode;
}

void printList(Node* head) {
    Node* current = head;
    while (current != nullptr) {
        cout << current->data << " -> ";
        current = current->next;
    }
    cout << "NULL" << endl;
}

void freeList(Node* head) {
    while (head != nullptr) {
        Node* old = head;
        head = head->next;
        delete old;
    }
}

int main() {
    Node* head = nullptr;
    append(&head, 10);
    append(&head, 20);
    append(&head, 30);
    printList(head);
    freeList(head);
    return 0;
}
